import { useState as useState10 } from "react";

// src/services/notifications.ts
function getNotificationPermission() {
  if (typeof window === "undefined" || !("Notification" in window)) {
    return { permission: "default", supported: false };
  }
  return { permission: Notification.permission, supported: true };
}
async function requestNotificationPermission() {
  if (typeof window === "undefined" || !("Notification" in window)) {
    return "denied";
  }
  try {
    const result = await Notification.requestPermission();
    return result;
  } catch {
    return "denied";
  }
}
function deliverDailyNotification(quote, timeOfDay = "morning", onInAppDeliver) {
  const title = timeOfDay === "morning" ? "\u2728 Morning Affirmation" : "\u{1F319} Evening Reflection";
  const body = `"${quote.text}" \u2014 ${quote.author}`;
  if (typeof window !== "undefined" && "Notification" in window && Notification.permission === "granted") {
    try {
      new Notification(title, {
        body,
        icon: "/favicon.ico",
        tag: `aura-quote-${quote.id}`
      });
      return true;
    } catch {
      onInAppDeliver?.(quote);
      return false;
    }
  } else {
    onInAppDeliver?.(quote);
    return false;
  }
}

